using FamilyVeda.Application.Portal;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace FamilyVeda.Api.Controllers;

[Route("api/v1/notifications")]
[Authorize]
public sealed class NotificationsController(IPortalNotificationService notificationService) : ApiControllerBase
{
    [HttpGet]
    public async Task<ActionResult<IReadOnlyList<PortalNotificationDto>>> GetMine(bool unreadOnly, CancellationToken cancellationToken) =>
        Ok(await notificationService.GetMineAsync(unreadOnly, cancellationToken));

    [HttpPost("{id:guid}/read")]
    public async Task<IActionResult> MarkRead(Guid id, CancellationToken cancellationToken)
    {
        await notificationService.MarkReadAsync(id, cancellationToken);
        return NoContent();
    }
}
